def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]

    if start_value == 0:
        return None

    change = end_value - start_value
    change_ratio = change / start_value

    return {
        "value": change_ratio,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
